from pathlib import Path
import json

T='BUILDPLAN-f13331a398cbc3d1890411e1c35abdae'
prod=Path.home()/'prediction_research_prod'
planner=prod/'control/codex_supervisor/build_planner.py'
text=planner.read_text(errors='replace')
lines=text.splitlines()
hits=[i for i,l in enumerate(lines) if 'NONBUILDABLE_COMPONENTS_MUST_BE_EMPTY' in l or 'nonbuildable_components' in l or 'buildable_components' in l]
print('PLANNER_PATH='+str(planner))
for i in sorted(set(hits)):
    a=max(0,i-18); b=min(len(lines),i+19)
    print(f'--- PLANNER_CONTEXT_{i+1} ---')
    for n in range(a,b): print(f'{n+1}: {lines[n]}')
runroot=prod/'knowledge/codex_runtime/runs'
for p in sorted(runroot.glob(T+'-*')):
    print('RUN_DIR='+str(p))
    for f in sorted(p.iterdir()):
        if not f.is_file(): continue
        print('FILE='+f.name)
        raw=f.read_text(errors='replace')
        if f.suffix=='.json':
            try:
                obj=json.loads(raw)
                print(json.dumps(obj,ensure_ascii=False,sort_keys=True)[:10000])
            except Exception:
                print(raw[:10000])
        elif f.name=='events.jsonl':
            for line in raw.splitlines()[-20:]: print(line[:2000])
        else:
            print(raw[-8000:])
